def attr(*args, **kwargs):
    """
    Ugly hack to render custom html5 data-* attributes
    on Django template.

    Pattern example (django-bootstrap-form.add_tag('data-idx: get_index;'.format(obj.pk))
    """
    classes_list = []
    for arg in args:
        classes_list.append(arg)
    for key, value in kwargs.items():
        classes_list.append('%s=%s' % (key, value))

    return mark_safe(format_html('< {}>', ' '.join(classes_list)))

